r"""Repo maintenance: clean .novc/, clean up finished agent worktrees, check
formatting, lint, run the test suite, run the routine rebuild.

Run from the repo root (each step resolves paths via ``mb_cmn.paths.repo_root()``):

    .venv/Scripts/python.exe py/main_repo_maintenance.py
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-novc
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-worktrees
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-black
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-lint
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-tests
    .venv/Scripts/python.exe py/main_repo_maintenance.py --skip-rebuild
    .venv/Scripts/python.exe py/main_repo_maintenance.py --continue-on-test-failure

Six independent steps, in order:

1. Wipe the gitignored ``.novc/`` scratch dir. There is ONE since 2026-08-12:
   this step wiped wlc-utils' as well while the code that wrote into it lived
   here and the corpus lived there, and that corpus came home
   (``doc/PLAN-evacuate-the-rest-of-wlc-utils.md``, Phases 3 and 5).
   Everything in it is MEANT to be a
   regenerable download cache or tool output, never a durable result -- but
   that is a rule about how to use the directory, not a fact about what is in
   it, and this step cannot tell the difference. It has already destroyed one
   durable result: a dual-cantillation survey that ``accgram.prose_filter``
   and ``tests/test_dual_cant_detangle`` both cited as their provenance.
   Before wiping, check that nothing in ``.novc/`` is the sole home of
   a decision or a pending item, and promote anything that is -- to an issue,
   to ``doc/``, or into the docstring of the code it explains.
   ``grep -rn '\.novc' py/ doc/`` finds the citations worth honouring.
2. Remove finished agent worktrees under ``.claude/worktrees/`` and the merged
   ``claude/*`` branches they leave behind
   (``repo_util.git_worktree_cleanup``). Unlike step 1 this one spares
   anything it could destroy: a worktree with any uncommitted change, any
   commit not yet in the default branch, or any gitignored content (the class
   of file step 1 wipes on purpose and this step must not wipe by accident --
   ``git worktree remove`` alone would) is kept and reported, never forced.
   This step is a repo-maintenance STANDARD, not one repo's quirk -- see
   ``repo_util/check_repo_standards.py``'s ``worktree_hygiene`` check, which
   measures every repo against it, and which this repo did not itself satisfy
   until the standard's reference implementation came home here.
3. Run ``black --check py``. Check-only: drift is reported, never
   auto-reformatted -- repo-wide reformatting is its own deliberate commit
   (see ``py/main_repo_util.py --run-black``). Failures set the overall exit
   status but do not block the later steps.
4. Run ``ruff check py`` (the linter, configured by ``ruff.toml``). Like
   black, lint failures set the overall exit status but do not block the
   later steps.
5. Run ``py/main_test.py``, this repo's canonical test entrypoint (see
   CLAUDE.md) -- a ``pytest.main()`` wrapper over the whole ``py/tests`` tree.
6. Run ``py/main_0_mega.py``, the routine downstream rebuild -- every
   parameterless, non-download rebuild step (parse, mam-with-doc,
   tmpl-survey, mam-simple, mam4sef/ajf, mam-osis, letter-small-job,
   decnreub, multimark, wordlist, explicit-xataf, the authored docs, the
   wlc steps -- vendor-uxlc, WLC JSON/Unicode, accgram, the 4.20/4.22
   diffs and the a-notes build -- and the closing vendoring audit).

The rebuild step is skipped if the test step failed, unless
``--continue-on-test-failure`` is given.
"""

import argparse
import shutil
import subprocess
import sys

from mb_cmn import paths
from repo_util import git_worktree_cleanup

_REPO = paths.repo_root()
_NOVC = paths.novc_dir()


def _parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--skip-novc", action="store_true", help="don't clean .novc/")
    parser.add_argument(
        "--skip-worktrees",
        action="store_true",
        help="don't remove finished agent worktrees and their merged branches",
    )
    parser.add_argument(
        "--skip-black", action="store_true", help="don't run black --check"
    )
    parser.add_argument("--skip-lint", action="store_true", help="don't run ruff")
    parser.add_argument(
        "--skip-tests", action="store_true", help="don't run the test suite"
    )
    parser.add_argument(
        "--skip-rebuild", action="store_true", help="don't run py/main_0_mega.py"
    )
    parser.add_argument(
        "--continue-on-test-failure",
        action="store_true",
        help="run the rebuild step even if a test failed",
    )
    return parser.parse_args()


def clean_novc() -> None:
    """Wipe the scratch dir.

    ONE, not two.  This wiped wlc-utils' ``.novc/`` as well until 2026-08-12: the
    ``accgram.gen_highlight_picker`` pages and ``accgram.scan_page`` renderings that land
    there are positioned relative to ``gh-pages/``, so they could not follow the code
    here in 2026-08-01's Python evacuation, and wlc-utils had no maintenance script of
    its own to wipe them.  ``gh-pages/`` came home at Phase 3 of
    ``doc/PLAN-evacuate-the-rest-of-wlc-utils.md`` and the writers were repointed at
    Phase 5, so the foreign wipe has nothing left to wipe.
    """
    _clean_one_novc(_NOVC, "MAM-basics")


def _clean_one_novc(novc, label: str) -> None:
    if not novc.exists():
        print(f"{label} .novc: nothing to clean (directory does not exist)")
        return
    removed = sorted(p.name for p in novc.iterdir())
    shutil.rmtree(novc)
    novc.mkdir()
    if removed:
        print(f"{label} .novc: removed {len(removed)} entries: {', '.join(removed)}")
    else:
        print(f"{label} .novc: already empty")


def clean_worktrees() -> bool:
    """Returns False only on a real failure -- a spared worktree is not one."""
    report = git_worktree_cleanup.clean_worktrees(_REPO)
    git_worktree_cleanup.print_report(report)
    return not report.errors


def run_black() -> bool:
    result = subprocess.run([sys.executable, "-m", "black", "--check", "py"], cwd=_REPO)
    ok = result.returncode == 0
    print(f"black: {'OK' if ok else f'FAILED (exit {result.returncode})'}")
    return ok


def run_lint() -> bool:
    result = subprocess.run([sys.executable, "-m", "ruff", "check", "py"], cwd=_REPO)
    ok = result.returncode == 0
    print(f"lint: {'OK' if ok else f'FAILED (exit {result.returncode})'}")
    return ok


def run_tests() -> bool:
    result = subprocess.run([sys.executable, "py/main_test.py"], cwd=_REPO)
    ok = result.returncode == 0
    print(f"tests: {'OK' if ok else f'FAILED (exit {result.returncode})'}")
    return ok


def run_rebuild() -> bool:
    script = _REPO / "py" / "main_0_mega.py"
    result = subprocess.run([sys.executable, str(script)], cwd=_REPO)
    print(
        "rebuild: OK"
        if result.returncode == 0
        else f"rebuild: FAILED (exit {result.returncode})"
    )
    return result.returncode == 0


def main() -> None:
    sys.stdout.reconfigure(encoding="utf-8", line_buffering=True)
    sys.stderr.reconfigure(encoding="utf-8")
    args = _parse_args()
    ok = True
    tests_ok = True

    if not args.skip_novc:
        clean_novc()

    if not args.skip_worktrees:
        ok = clean_worktrees() and ok

    if not args.skip_black:
        ok = run_black() and ok

    if not args.skip_lint:
        ok = run_lint() and ok

    if not args.skip_tests:
        tests_ok = run_tests()
        ok = tests_ok and ok

    if not args.skip_rebuild:
        if tests_ok or args.continue_on_test_failure:
            ok = run_rebuild() and ok
        else:
            print(
                "rebuild: skipped (tests failed; pass --continue-on-test-failure "
                "to run anyway)"
            )
            ok = False

    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    main()
